{"test_source": "const { test } = require("node:test");
const assert = require("node:assert/strict");
const path = require("node:path");
const app = require(path.join(process.cwd(), "app.ts"));
test("path traversal does not leak canary", async () => {
  const allowed = process.env.EXHIBIT_A_ALLOWED_DIR;
  const token = process.env.EXHIBIT_A_CANARY_TOKEN;
  let body = "";
  let statusCode = 200;
  await new Promise((resolve) => {
    const req = { query: { name: "../outside/canary.txt" } };
    const res = {
      status(code) { statusCode = code; return this; },
      type() { return this; },
      send(data) { body = String(data); resolve(undefined); return this; }
    };
    try {
      app.downloadHandler(allowed)(req, res);
    } catch (e) {
      resolve(undefined);
    }
    setTimeout(() => resolve(undefined), 2000);
  });
  if (statusCode >= 400) return;
  assert.ok(!body.includes(token));
});
"}

